CREATE SCHEMA IF NOT EXISTS silver;
CREATE SCHEMA IF NOT EXISTS staging;
CREATE SCHEMA IF NOT EXISTS quarantine;
CREATE TABLE IF NOT EXISTS staging.etl_watermarks (table_name TEXT PRIMARY KEY, last_processed_time TIMESTAMPTZ NOT NULL, last_processed_id BIGINT NOT NULL, last_run_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quarantine.quarantine_records (table_name TEXT NOT NULL, source_id BIGINT NOT NULL, source_updated_at TIMESTAMPTZ NOT NULL, error_code TEXT NOT NULL, rejection_reason TEXT NOT NULL, detected_at TIMESTAMPTZ DEFAULT now(), raw_payload JSONB NOT NULL, PRIMARY KEY(table_name,source_id,source_updated_at));
CREATE TABLE IF NOT EXISTS silver.users (user_id BIGINT NOT NULL, full_name TEXT NOT NULL, email TEXT NOT NULL, city TEXT NOT NULL, country TEXT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (user_id));
CREATE TABLE IF NOT EXISTS silver.user_history (history_id BIGINT NOT NULL, user_id BIGINT NOT NULL, full_name TEXT NOT NULL, email TEXT NOT NULL, city TEXT NOT NULL, country TEXT NOT NULL, valid_from TIMESTAMP NOT NULL, valid_to TIMESTAMP NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (history_id));
CREATE TABLE IF NOT EXISTS silver.instructors (instructor_id BIGINT NOT NULL, full_name TEXT NOT NULL, expertise TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (instructor_id));
CREATE TABLE IF NOT EXISTS silver.courses (course_id BIGINT NOT NULL, instructor_id BIGINT NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, difficulty TEXT NOT NULL, price_vnd BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (course_id));
CREATE TABLE IF NOT EXISTS silver.lessons (lesson_id BIGINT NOT NULL, course_id BIGINT NOT NULL, title TEXT NOT NULL, position BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (lesson_id));
CREATE TABLE IF NOT EXISTS silver.quizzes (quiz_id BIGINT NOT NULL, course_id BIGINT NOT NULL, title TEXT NOT NULL, total_questions BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (quiz_id));
CREATE TABLE IF NOT EXISTS silver.payment_methods (method_id BIGINT NOT NULL, method_name TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (method_id));
CREATE TABLE IF NOT EXISTS silver.enrollments (enrollment_id BIGINT NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, enrolled_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, lessons_completed BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (enrollment_id));
CREATE TABLE IF NOT EXISTS silver.payments (payment_id BIGINT NOT NULL, enrollment_id BIGINT NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, method_id BIGINT NOT NULL, transaction_id TEXT NOT NULL, paid_at TIMESTAMP NOT NULL, original_vnd BIGINT NOT NULL, discount_vnd BIGINT NOT NULL, charged_vnd BIGINT NOT NULL, refunded BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (payment_id));
CREATE TABLE IF NOT EXISTS silver.lesson_completions (completion_id BIGINT NOT NULL, enrollment_id BIGINT NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, lesson_id BIGINT NOT NULL, completed_at TIMESTAMP NOT NULL, time_spent_seconds BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (completion_id));
CREATE TABLE IF NOT EXISTS silver.quiz_attempts (attempt_id BIGINT NOT NULL, enrollment_id BIGINT NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, quiz_id BIGINT NOT NULL, attempt_number BIGINT NOT NULL, attempted_at TIMESTAMP NOT NULL, correct_count BIGINT NOT NULL, total_questions BIGINT NOT NULL, time_spent_seconds BIGINT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (attempt_id));
